const ReplayManager = {
  active: false,
  playing: false,
  speed: 1,
  currentIndex: 0,
  timerId: null,
  finalSnapshot: null,

  startFullscreenReplay() {
    if (!Array.isArray(GameState.replayFrames) || GameState.replayFrames.length < 2) {
      SoundEngine.invalid();
      showBoardToast('No moves recorded to replay yet!');
      return;
    }

    if (!this.active) {
      this.finalSnapshot = {
        board: [...GameState.board],
        kings: [...GameState.kings],
        reserves: { ...GameState.reserves },
        capturedBy: { ...GameState.capturedBy },
        currentTurn: GameState.currentTurn,
        lastMove: GameState.lastMove ? { ...GameState.lastMove } : null,
        lastFormedMill: GameState.lastFormedMill ? [...GameState.lastFormedMill] : null,
        gomokuWinningLine: GameState.gomokuWinningLine ? [...GameState.gomokuWinningLine] : null,
        gameOver: GameState.gameOver,
        winner: GameState.winner,
        winReason: GameState.winReason
      };
    }

    this.active = true;
    this.playing = false;
    document.body.classList.add('replay-mode');

    const modalVictory = document.getElementById('modalVictory');
    if (modalVictory) {
      modalVictory.classList.add('hidden');
      modalVictory.classList.remove('flex');
    }
    const inspectBar = document.getElementById('victoryInspectBar');
    if (inspectBar) inspectBar.classList.add('hidden');

    const bar = document.getElementById('replayControllerBar');
    if (bar) bar.classList.remove('hidden');

    const scrubber = document.getElementById('rngReplayScrubber');
    if (scrubber) {
      scrubber.min = '0';
      scrubber.max = String(GameState.replayFrames.length - 1);
      scrubber.value = '0';
    }

    Immersive.enter();
    this.seekTo(0, false);
    resizeCanvas();
    showBoardToast('🎬 Fullscreen Replay Started — Use controls below or Spacebar to Play/Pause');

    setTimeout(() => {
      if (this.active) this.play();
    }, 350);
  },

  seekTo(index, animate = true) {
    if (!Array.isArray(GameState.replayFrames) || GameState.replayFrames.length === 0) return;
    const maxIdx = GameState.replayFrames.length - 1;
    const clamped = Math.max(0, Math.min(maxIdx, index));
    const prevIdx = this.currentIndex;
    this.currentIndex = clamped;

    const frame = GameState.replayFrames[clamped];
    if (!frame) return;

    GameState.board = [...frame.board];
    GameState.kings = [...frame.kings];
    GameState.reserves = { ...frame.reserves };
    GameState.capturedBy = { ...frame.capturedBy };
    GameState.currentTurn = frame.currentTurn;
    GameState.selectedNode = null;
    GameState.chainJumpingNode = null;
    GameState.morrisPendingRemove = false;
    GameState.lastMove = frame.lastMove ? { ...frame.lastMove } : null;
    GameState.lastFormedMill = frame.lastFormedMill ? [...frame.lastFormedMill] : null;
    GameState.gomokuWinningLine = frame.gomokuWinningLine ? [...frame.gomokuWinningLine] : null;
    VisualFX.hintHighlight = null;

    if (animate && clamped === prevIdx + 1 && frame.lastMove) {
      const lm = frame.lastMove;
      if (lm.from !== null && lm.from !== undefined && lm.from >= 0 && lm.to !== null && lm.to !== undefined && lm.to >= 0) {
        const fromNode = Nodes[lm.from];
        const toNode = Nodes[lm.to];
        if (fromNode && toNode) {
          VisualFX.startPieceTween(fromNode, toNode, lm.player, lm.type === 'jump');
        }
      } else if (lm.type === 'drop' && lm.to !== null && lm.to !== undefined && lm.to >= 0) {
        VisualFX.spawnPulseRing(lm.to, lm.player === 1 ? '#0D9488' : '#E11D48');
      }

      if (Array.isArray(lm.capturedIds) && lm.capturedIds.length > 0) {
        const victimPlayer = lm.player === 1 ? 2 : 1;
        for (const cid of lm.capturedIds) {
          if (Nodes[cid]) {
            VisualFX.spawnCaptureBurst(Nodes[cid].x, Nodes[cid].y, victimPlayer);
          }
        }
        SoundEngine.capture(lm.capturedIds.length);
      } else {
        SoundEngine.move();
      }
    } else {
      VisualFX.movingPiece = null;
    }

    updateHUD();
    this.syncControlsUI();
    requestRender();
  },

  getStepIntervalMs() {
    return Math.max(220, Math.round(920 / (this.speed || 1)));
  },

  scheduleNextStep() {
    if (this.timerId) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
    if (!this.active || !this.playing) return;
    this.timerId = setTimeout(() => {
      this.timerId = null;
      if (!this.active || !this.playing) return;
      if (this.currentIndex < GameState.replayFrames.length - 1) {
        this.seekTo(this.currentIndex + 1, true);
        if (this.currentIndex >= GameState.replayFrames.length - 1) {
          this.playing = false;
          SoundEngine.victory();
          this.syncControlsUI();
        } else {
          this.scheduleNextStep();
        }
      } else {
        this.playing = false;
        this.syncControlsUI();
      }
    }, this.getStepIntervalMs());
  },

  play() {
    if (!this.active) return;
    if (this.currentIndex >= GameState.replayFrames.length - 1) {
      this.seekTo(0, false);
    }
    this.playing = true;
    this.syncControlsUI();
    this.scheduleNextStep();
  },

  pause() {
    this.playing = false;
    if (this.timerId) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
    this.syncControlsUI();
  },

  stop() {
    this.pause();
    this.seekTo(0, false);
    const statusTxt = document.getElementById('replayStatusText');
    const statusDot = document.getElementById('replayStatusDot');
    const statusBadge = document.getElementById('replayStatusBadge');
    if (statusTxt) statusTxt.textContent = 'Stopped';
    if (statusDot) statusDot.className = 'w-2 h-2 rounded-full bg-white';
    if (statusBadge) statusBadge.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-rose-600 text-white font-black text-[10px] tracking-wider uppercase shrink-0';
  },

  togglePlayPause() {
    if (!this.active) return;
    SoundEngine.select();
    if (this.playing) this.pause();
    else this.play();
  },

  stepPrev() {
    if (!this.active) return;
    this.pause();
    SoundEngine.select();
    this.seekTo(this.currentIndex - 1, false);
  },

  stepNext() {
    if (!this.active) return;
    this.pause();
    this.seekTo(this.currentIndex + 1, true);
  },

  setSpeed(newSpeed) {
    const sp = Number(newSpeed) || 1;
    this.speed = sp;
    SoundEngine.select();
    this.syncControlsUI();
    if (this.playing) {
      this.scheduleNextStep();
    }
  },

  syncControlsUI() {
    const total = Math.max(0, (GameState.replayFrames ? GameState.replayFrames.length : 1) - 1);
    const frame = (GameState.replayFrames && GameState.replayFrames[this.currentIndex]) || null;

    const scrubber = document.getElementById('rngReplayScrubber');
    if (scrubber) {
      scrubber.max = String(total);
      scrubber.value = String(this.currentIndex);
    }

    const countEl = document.getElementById('replayFrameCount');
    if (countEl) countEl.textContent = `Move ${this.currentIndex} / ${total}`;

    const lblMove = document.getElementById('replayMoveLabel');
    if (lblMove && frame) lblMove.textContent = frame.label || 'Initial Board Setup';

    const iconPP = document.getElementById('iconReplayPlayPause');
    const lblPP = document.getElementById('lblReplayPlayPause');
    const isAtEnd = this.currentIndex >= total;
    if (iconPP) iconPP.textContent = this.playing ? '⏸' : (isAtEnd ? '↺' : '▶');
    if (lblPP) lblPP.textContent = this.playing ? 'Pause' : (isAtEnd ? 'Replay' : 'Play');

    const statusTxt = document.getElementById('replayStatusText');
    const statusDot = document.getElementById('replayStatusDot');
    const statusBadge = document.getElementById('replayStatusBadge');
    if (statusTxt && statusDot && statusBadge) {
      if (this.playing) {
        statusTxt.textContent = `Playing ${this.speed}×`;
        statusDot.className = 'w-2 h-2 rounded-full bg-walnut-900 animate-ping';
        statusBadge.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-amber-400 text-walnut-900 font-black text-[10px] tracking-wider uppercase shrink-0';
      } else if (isAtEnd) {
        statusTxt.textContent = 'Finished';
        statusDot.className = 'w-2 h-2 rounded-full bg-emerald-200';
        statusBadge.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-emerald-600 text-white font-black text-[10px] tracking-wider uppercase shrink-0';
      } else {
        statusTxt.textContent = 'Paused';
        statusDot.className = 'w-2 h-2 rounded-full bg-amber-300';
        statusBadge.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-white/15 text-amber-200 font-black text-[10px] tracking-wider uppercase shrink-0';
      }
    }

    const immTurnText = document.getElementById('immTurnText');
    if (immTurnText && frame) {
      immTurnText.textContent = `🎬 Replay (${this.currentIndex}/${total}) • ${frame.label}`;
    }

    document.querySelectorAll('.replay-speed-btn').forEach((btn) => {
      const s = Number(btn.getAttribute('data-replay-speed'));
      if (s === this.speed) {
        btn.className = 'replay-speed-btn android-btn px-1.5 sm:px-2 py-1 rounded-lg text-[10px] font-mono font-extrabold bg-teal-600 text-white shadow';
      } else {
        btn.className = 'replay-speed-btn android-btn px-1.5 sm:px-2 py-1 rounded-lg text-[10px] font-mono font-extrabold text-parchment-200 hover:bg-white/10';
      }
    });
  },

  close(reopenVictory = true) {
    if (!this.active) return;
    this.pause();
    this.active = false;
    document.body.classList.remove('replay-mode');

    const bar = document.getElementById('replayControllerBar');
    if (bar) bar.classList.add('hidden');

    if (this.finalSnapshot) {
      GameState.board = [...this.finalSnapshot.board];
      GameState.kings = [...this.finalSnapshot.kings];
      GameState.reserves = { ...this.finalSnapshot.reserves };
      GameState.capturedBy = { ...this.finalSnapshot.capturedBy };
      GameState.currentTurn = this.finalSnapshot.currentTurn;
      GameState.lastMove = this.finalSnapshot.lastMove ? { ...this.finalSnapshot.lastMove } : null;
      GameState.lastFormedMill = this.finalSnapshot.lastFormedMill ? [...this.finalSnapshot.lastFormedMill] : null;
      GameState.gomokuWinningLine = this.finalSnapshot.gomokuWinningLine ? [...this.finalSnapshot.gomokuWinningLine] : null;
      GameState.gameOver = this.finalSnapshot.gameOver;
      GameState.winner = this.finalSnapshot.winner;
      GameState.winReason = this.finalSnapshot.winReason;
      this.finalSnapshot = null;
    }

    VisualFX.movingPiece = null;
    if (Immersive.active) {
      Immersive.exit();
    } else {
      resizeCanvas();
    }
    updateHUD();
    requestRender();
    if (reopenVictory && GameState.gameOver) {
      showVictoryModal(true);
    }
  }
};

